sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float strength;
uniform float2 center;

half4 main(float2 coord) {
    float2 centerCoord = center * size;
    float2 dir = coord - centerCoord;
    half3 sumRGB = half3(0);
    half sumAlpha = 0.0;
    half count = 0.0;
    for (int i = 0; i < 32; ++i) {
        float t = (float(i) / 31.0) * strength;
        float2 pos = centerCoord + dir * t;
        half4 c = image.eval(pos);
        half a = c.a;
        if (a <= 1e-4) continue;
        half invA = 1.0 / a;
        half3 unprem = c.rgb * invA;
        sumRGB += unprem;
        sumAlpha += a;
        count += 1.0;
    }
    if (count == 0) {
        return half4(0, 0, 0, 0);
    }
    half avgAlpha = sumAlpha / count;
    half3 avg = sumRGB / count;
    half3 finalRGB = avg * avgAlpha;
    return half4(finalRGB, avgAlpha);
}
